/**
 * The wash levels of a family (spec 9.1, #1414, #1427): a background named by how marked it is.
 * A colored hue publishes them as `--magma-<hue>-wash-*`, the neutral band as `--magma-wash-*`,
 * an accent as `--magma-accent(-ai)-surface*`; each resolves to a generated primitive,
 * `--wash-<family>-<level>` (`state-color.mts`).
 *
 * The levels are GENERATED by lightness from the key colour of the family, with the engine of
 * the surfaces (`lightnessColor` of `surface.mts`), at a fixed distance from the page: below it
 * in light, mirrored above it in dark (#1427). They used to be steps of the family's own ramp
 * (10/09/08), which do not follow the surfaces: the ramp of the accent, generated in HSL, gave
 * grey washes in light (chroma 0.004-0.021), and every ramp gave dark washes 20-33 dE from the
 * page against 7-15 in light, the "brick" of the board of mds-button.
 *
 * One definition for the four that read it, so they cannot drift:
 *  - the engine places the levels (`state-color.mts`);
 *  - the semantic layer names them (`semantic.config.ts`, `washLevels`);
 *  - the text-role engine solves each text role against the washes of its family it must be
 *    legible on, beside the surfaces (`text-role.mts`, #1414);
 *  - the contrast gate holds the same pairs to the same floors (`contrast-gate.ts`).
 */

/**
 * The distance of each wash level from the page (`theme.surfaces.<mode>.default` of the family),
 * in OKLCH lightness x 100. Criteria (#1427):
 *  - `soft`, `base`, `strong`: the distances of the light washes of `variant-primary` before
 *    #1427 (ramp steps 10/09/08 at L 94.6/90.6/86.8 on the page at L 97.9), the weight the
 *    components were drawn with;
 *  - `selected`: between `base` and `strong`, the area of a selected weak control, which weighs
 *    less than its hover (`strong`) and more than its rest (`base`, #1264). Not midway (9.2): on
 *    the page of the palette of #1460 (L 96) `text-default`, already the darkest step of its
 *    ramp, measured Lc 73.1-74.8 there for the accents, warning and danger, under the 75 floor it
 *    carries on this level. 8.2 is the farthest level from the page that holds 75 for every
 *    family in every theme (measured 2026-11-24: 8.4 left 4 pairs, 8.2 none);
 *  - `soft-selected`: half of `soft`, midway between the page and `soft`, the area of a selected
 *    control with no area at rest (text, outline) whose hover is `soft`.
 * Ordered from the least marked to the most marked.
 */
export const WASH_LEVELS = {
  'soft-selected': 1.65,
  soft: 3.3,
  base: 7.3,
  selected: 8.2,
  strong: 11.1,
} as const;

export type WashLevel = keyof typeof WASH_LEVELS;

/**
 * Which text roles are ENFORCED on each wash level (spec 9.1) - for the colored
 * hues, the accents AND the neutral band of 6.1b. This is the contract for a pill-shaped
 * background, and it is bounded by measurement, not taste: the more marked the
 * wash, the less of the text ladder it can carry.
 *  - `soft` (the lightest wash) carries the whole ladder;
 *  - `base` carries `text-default` only (`muted` measures 73-75 Lc on it,
 *    i.e. at or just under its 75 floor);
 *  - `strong` carries NO essential text: it is the graphic wash (chips,
 *    cockades, hover) and only has to keep icons legible, which the report-only
 *    target covers (`text-default` measures 74.5-76 Lc there).
 * Roles left out of a level are still measured and reported by the gate, just not gated.
 * The two selected levels follow the same rule by where they sit (#1427): `soft-selected`, less
 * marked than `soft`, carries the whole ladder; `selected`, between `base` and `strong`, carries
 * `text-default`, which is the label of a selected weak control.
 *
 * ONE table for both bands because the measurement says so, not for symmetry.
 * Measured on the neutral band the day it was added (#624): `soft` 95.3/96.8 Lc
 * for `default` down to 60.4/61.8 for `disabled` (light/dark, all above their
 * floors); `base` 88.4/89.5 for `default` but 73.1/74.0 for `muted`, under the
 * 75 floor exactly as on a hue; `strong` 78.7/79.9 for `default`, which clears
 * the icon target but leaves no headroom for a ladder.
 */
export const WASH_TEXT_ENFORCED: Record<WashLevel, readonly string[]> = {
  'soft-selected': ['default', 'muted', 'subtle', 'disabled'],
  soft: ['default', 'muted', 'subtle', 'disabled'],
  base: ['default'],
  selected: ['default'],
  strong: [],
};
